import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { RapierPhysics } from '@dimforge/rapier3d-compat';
import { useGameStore } from './store/gameStore';
import { useParrySystem } from './hooks/useParrySystem';
import { useBossRush } from './hooks/useBossRush';

const App: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { initializePhysics, updatePhysics } = useGameStore();

  useEffect(() => {
    if (!containerRef.current) return;

    // Initialize Three.js scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0a0a);
    scene.fog = new THREE.Fog(0x0a0a0a, 10, 1000);

    // Camera with Dark Souls-style perspective
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      2000
    );
    camera.position.set(0, 1.8, 5);

    // Renderer with anti-aliasing
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.8;

    containerRef.current.appendChild(renderer.domElement);

    // Lighting for Dark Souls atmosphere
    const ambientLight = new THREE.AmbientLight(0x404040, 0.3);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(10, 20, 10);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    scene.add(directionalLight);

    // Initialize physics
    let physicsPromise: Promise<void>;
    if (typeof window !== 'undefined') {
      physicsPromise = initializePhysics();
    }

    // Handle window resize
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate);

      if (physicsPromise) {
        updatePhysics();
      }

      // Update game systems
      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      if (containerRef.current?.contains(renderer.domElement)) {
        containerRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [initializePhysics, updatePhysics]);

  return (
    <div className="game-container">
      <div ref={containerRef} className="canvas-container" />
      <div className="ui-overlay">
        <div className="health-bar" />
        <div className="parry-indicator" />
        <div className="boss-progress" />
      </div>
    </div>
  );
};

export default App;

import { create } from 'zustand';
import { Vector3 } from 'three';

interface GameState {
  // Game state
  isGameStarted: boolean;
  currentLevel: number;
  currentBoss: number;
  score: number;
  health: number;
  maxHealth: number;

  // Parry system
  parryActive: boolean;
  parryCooldown: number;
  lastParryTime: number;

  // Physics
  physicsInitialized: boolean;

  // UI
  gameOver: boolean;
  victory: boolean;

  // Actions
  startGame: () => void;
  updateLevel: (level: number) => void;
  updateHealth: (health: number) => void;
  triggerParry: () => void;
  activateParryWindow: () => void;
  initializePhysics: () => Promise<void>;
  updatePhysics: () => void;
  resetGame: () => void;
}

export const useGameStore = create<GameState>((set, get) => ({
  // Initial state
  isGameStarted: false,
  currentLevel: 1,
  currentBoss: 1,
  score: 0,
  health: 100,
  maxHealth: 100,
  parryActive: false,
  parryCooldown: 0,
  lastParryTime: 0,
  physicsInitialized: false,
  gameOver: false,
  victory: false,

  // Actions
  startGame: () => set({ 
    isGameStarted: true, 
    health: 100, 
    currentLevel: 1, 
    score: 0,
    gameOver: false,
    victory: false
  }),

  updateLevel: (level) => set({ 
    currentLevel: level,
    currentBoss: level,
    health: 100
  }),

  updateHealth: (health) => set({ 
    health,
    ...(health <= 0 && { gameOver: true })
  }),

  triggerParry: () => set((state) => ({
    parryActive: true,
    lastParryTime: Date.now(),
    parryCooldown: 2000 // 2 second cooldown
  })),

  activateParryWindow: () => set({ 
    parryActive: true,
    parryCooldown: 0
  }),

  initializePhysics: async () => {
    // This will be called when the physics engine is ready
    set({ physicsInitialized: true });
  },

  updatePhysics: () => {
    const state = get();

    // Update parry cooldown
    if (state.parryCooldown > 0) {
      set({ 
        parryCooldown: Math.max(0, state.parryCooldown - 16) // 60fps update
      });
    }

    // Auto-deactivate parry after timing
    if (state.parryActive && Date.now() - state.lastParryTime > 500) {
      set({ parryActive: false });
    }
  },

  resetGame: () => set({
    isGameStarted: false,
    currentLevel: 1,
    currentBoss: 1,
    score: 0,
    health: 100,
    parryActive: false,
    parryCooldown: 0,
    lastParryTime: 0,
    gameOver: false,
    victory: false
  })
}));

import { useEffect, useCallback } from 'react';
import { useGameStore } from '../store/gameStore';

export const useParrySystem = () => {
  const { 
    activateParryWindow, 
    triggerParry, 
    updateHealth,
    score,
    currentLevel
  } = useGameStore();

  // Parry input handling
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Parry key (Space bar)
      if (event.code === 'Space' && !event.repeat) {
        event.preventDefault();

        // Check if parry window is active
        const parryWindowActive = Math.random() < 0.3; // 30% chance for parry window

        if (parryWindowActive) {
          // Successful parry
          triggerParry();

          // Parried attack - reduce damage taken
          const parryDamageReduction = 0.7; // 70% damage reduction
          const newHealth = Math.max(0, 100 - (currentLevel * 5 * parryDamageReduction));
          updateHealth(newHealth);

          // Increase score for successful parry
          const newScore = score + 100;
          // Note: score update would be handled in the store
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activateParryWindow, triggerParry, updateHealth, score, currentLevel]);

  // Parry window system (enemy attacks)
  useEffect(() => {
    const parryInterval = setInterval(() => {
      if (Math.random() < 0.02) { // 2% chance per frame
        activateParryWindow();
      }
    }, 1000); // Check every second

    return () => clearInterval(parryInterval);
  }, [activateParryWindow]);

  return {
    // Parry system functions
  };
};

import { useEffect, useCallback } from 'react';
import { useGameStore } from '../store/gameStore';

export const useBossRush = () => {
  const { 
    currentLevel, 
    updateLevel, 
    updateHealth,
    score,
    startGame,
    resetGame
  } = useGameStore();

  const bosses = [
    {
      id: 1,
      name: "Lich Lord",
      health: 80,
      attackPattern: "Slow, powerful magic",
      parryWindow: 0.3, // 30% chance
      reward: 500
    },
    {
      id: 2,
      name: "Golem",
      health: 120,
      attackPattern: "Charge attacks, heavy armor",
      parryWindow: 0.2, // 20% chance
      reward: 800
    },
    {
      id: 3,
      name: "Skeleton King",
      health: 60,
      attackPattern: "Ranged attacks,召唤 minions",
      parryWindow: 0.25, // 25% chance
      reward: 600
    },
    {
      id: 4,
      name: "Dragonlord",
      health: 150,
      attackPattern: "Fire breath, flying attacks",
      parryWindow: 0.15, // 15% chance
      reward: 1000
    },
    {
      id: 5,
      name: "The Great Lord",
      health: 200,
      attackPattern: "Massive, unpredictable combos",
      parryWindow: 0.1, // 10% chance
      reward: 2000
    }
  ];

  const startBossEncounter = useCallback(() => {
    const boss = bosses[currentLevel - 1];
    if (!boss) return;

    // Initialize boss encounter
    updateHealth(boss.health);

    // Start parry system for this boss
    const parryInterval = setInterval(() => {
      // Simulate boss attack patterns
      const attackChance = Math.random();

      if (attackChance < boss.parryWindow) {
        // Boss is attacking, activate parry window
        // This would trigger in the parry system
        console.log(`${boss.name} attacks! Parry now!`);
      }
    }, 2000);

    return () => clearInterval(parryInterval);
  }, [currentLevel, updateHealth, bosses]);

  const nextLevel = useCallback(() => {
    if (currentLevel < bosses.length) {
      updateLevel(currentLevel + 1);
      startBossEncounter();
    } else {
      // Game completed
      console.log("Congratulations! You defeated all bosses!");
      // Update victory state in store
    }
  }, [currentLevel, updateLevel, startBossEncounter]);

  const takeDamage = useCallback((damage: number) => {
    const newHealth = Math.max(0, (useGameStore.getState().health || 100) - damage);
    updateHealth(newHealth);

    if (newHealth <= 0) {
      console.log("Game Over! You were defeated.");
      // Game over would be handled in store
    }
  }, [updateHealth]);

  useEffect(() => {
    if (currentLevel > 0 && currentLevel <= bosses.length) {
      startBossEncounter();
    }
  }, [currentLevel, startBossEncounter]);

  return {
    bosses,
    currentBoss: bosses[currentLevel - 1],
    nextLevel,
    takeDamage,
    startGame,
    resetGame
  };
};

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  overflow: hidden;
  background-color: #000;
}

.game-container {
  width: 100vw;
  height: 100vh;
  position: relative;
}

.canvas-container {
  width: 100%;
  height: 100%;
}

.ui-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  padding: 20px;
  pointer-events: none;
  z-index: 100;
}

.health-bar {
  width: 300px;
  height: 30px;
  background: linear-gradient(135deg, #ff6b6b, #ff4757);
  border: 2px solid #fff;
  border-radius: 15px;
  box-shadow: 0 0 20px rgba(255, 107, 107, 0.5);
  transition: width 0.3s ease;
}

.parry-indicator {
  position: absolute;
  top: 80px;
  right: 20px;
  width: 200px;
  height: 60px;
  background: rgba(0, 255, 255, 0.1);
  border: 2px solid #00ffff;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #00ffff;
  font-weight: bold;
  font-size: 14px;
  animation: pulse 2s infinite;
}

.parry-indicator.active {
  background: rgba(0, 255, 255, 0.3);
  box-shadow: 0 0 30px rgba(0, 255, 255, 0.8);
}

.boss-progress {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  width: 400px;
  height: 20px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid #fff;
  border-radius: 10px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #ffd700, #ffed4e);
  transition: width 0.3s ease;
}

.game-over, .victory-screen {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  color: white;
  z-index: 200;
  pointer-events: auto;
}

.restart-button {
  margin-top: 20px;
  padding: 15px 30px;
  background: linear-gradient(135deg, #ff6b6b, #ff4757);
  border: none;
  border-radius: 10px;
  color: white;
  font-size: 18px;
  font-weight: bold;
  cursor: pointer;
  transition: transform 0.2s;
}

.restart-button:hover {
  transform: scale(1.05);
}

@keyframes pulse {
  0%, 100% { opacity: 0.6; }
  50% { opacity: 1; }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}

.shake {
  animation: shake 0.5s;
}

.instructions {
  position: absolute;
  bottom: 10px;
  left: 10px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
  pointer-events: none;
}

import React from 'react';
import { useGameStore } from '../store/gameStore';

interface GameUIProps {
  onRestart: () => void;
}

export const GameUI: React.FC<GameUIProps> = ({ onRestart }) => {
  const { 
    health, 
    maxHealth, 
    gameOver, 
    victory,
    parryActive
  } = useGameStore();

  if (gameOver) {
    return (
      <div className="game-over">
        <h1>Game Over</h1>
        <p>You were defeated by the bosses</p>
        <button onClick={onRestart} className="restart-button">
          Try Again
        </button>
      </div>
    );
  }

  if (victory) {
    return (
      <div className="victory-screen">
        <h1>Victory!</h1>
        <p>You have conquered all bosses</p>
        <button onClick={onRestart} className="restart-button">
          Boss Rush Again
        </button>
      </div>
    );
  }

  return (
    <div className="ui-overlay">
      <div className="health-container">
        <div 
          className="health-bar" 
          style={{ width: `${(health / maxHealth) * 100}%` }}
        />
        <div className="health-text">
          Health: {health}/{maxHealth}
        </div>
      </div>

      <div className={`parry-indicator ${parryActive ? 'active' : ''}`}>
        {parryActive ? 'PARRY NOW!' : 'Ready to Parry'}
      </div>

      <div className="boss-progress">
        <div 
          className="progress-fill" 
          style={{ width: `${((useGameStore.getState().currentLevel || 1) / 5) * 100}%` }}
        />
      </div>

      <div className="instructions">
        <p>SPACE - Parry Attack</p>
        <p>A/D - Move</p>
        <p>W - Block</p>
      </div>
    </div>
  );
};

