import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { useGameStore } from './store/gameStore';
import { useParrySystem } from './hooks/useParrySystem';
import { useBossRush } from './hooks/useBossRush';
import { GameUI } from './components/GameUI';
import testRunner from './testRunner';

const App: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { 
    initializePhysics, 
    updatePhysics,
    startGame,
    resetGame,
    isGameStarted,
    gameOver,
    victory
  } = useGameStore();

  // Initialize game systems
  useEffect(() => {
    // Run validation tests before starting
    testRunner.runPreGameTests().then((success) => {
      if (success) {
        console.log("✅ All systems validated. Ready for Boss Rush!");
      } else {
        console.error("❌ System validation failed");
      }
    });

    // Start game automatically
    startGame();
  }, [startGame]);

  // Setup Three.js scene and physics
  useEffect(() => {
    if (!containerRef.current || !isGameStarted) return;

    // Initialize Three.js scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0a0a);
    scene.fog = new THREE.Fog(0x0a0a0a, 10, 1000);

    // Camera with Dark Souls-style perspective
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      2000
    );
    camera.position.set(0, 1.8, 5);

    // Renderer with anti-aliasing
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.8;

    containerRef.current.appendChild(renderer.domElement);

    // Lighting for Dark Souls atmosphere
    const ambientLight = new THREE.AmbientLight(0x404040, 0.3);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(10, 20, 10);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    scene.add(directionalLight);

    // Initialize physics
    let physicsInitialized = false;
    const initPhysics = async () => {
      try {
        await initializePhysics();
        physicsInitialized = true;
        console.log("✅ Physics system initialized");
      } catch (error) {
        console.error("❌ Physics initialization failed:", error);
      }
    };

    initPhysics();

    // Handle window resize
    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    // Animation loop
    const animate = () => {
      requestAnimationFrame(animate);

      if (physicsInitialized) {
        updatePhysics();
      }

      // Update game systems
      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      if (containerRef.current?.contains(renderer.domElement)) {
        containerRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [initializePhysics, updatePhysics, isGameStarted]);

  // Initialize game systems
  useParrySystem();
  const { startGame: startBossRush, resetGame: resetBossRush } = useBossRush();

  return (
    <div className="game-container">
      <div ref={containerRef} className="canvas-container" />
      <GameUI onRestart={resetGame} />
    </div>
  );
};

export default App;

import * as THREE from 'three';

export class EnemyModels {
  private scene: THREE.Scene;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
  }

  createBossEnemy(bossId: number): THREE.Group {
    const boss = new THREE.Group();
    boss.userData.bossId = bossId;

    // Create boss body (Dark Souls style)
    const bodyGeometry = new THREE.BoxGeometry(2, 3, 1.5);
    const bodyMaterial = new THREE.MeshPhongMaterial({
      color: 0x404040,
      shininess: 30,
      emissive: 0x111111
    });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.castShadow = true;
    body.receiveShadow = true;
    boss.add(body);

    // Create boss head (helmet)
    const headGeometry = new THREE.BoxGeometry(1.8, 1.5, 1.2);
    const headMaterial = new THREE.MeshPhongMaterial({
      color: 0x606060,
      shininess: 20,
      emissive: 0x222222
    });
    const head = new THREE.Mesh(headGeometry, headMaterial);
    head.position.y = 2.5;
    head.castShadow = true;
    boss.add(head);

    // Create boss weapon (axe for melee, staff for ranged)
    const weaponGeometry = new THREE.BoxGeometry(0.3, 2, 0.3);
    const weaponMaterial = new THREE.MeshPhongMaterial({
      color: 0x8b4513,
      shininess: 40
    });
    const weapon = new THREE.Mesh(weaponGeometry, weaponMaterial);
    weapon.position.set(1.5, 1, 0);
    boss.add(weapon);

    // Create boss armor plates
    this.createArmorPlates(boss);

    // Add boss-specific effects based on ID
    this.addBossSpecificEffects(boss, bossId);

    return boss;
  }

  private createArmorPlates(boss: THREE.Group) {
    // Create plate armor pieces
    const plateGeometry = new THREE.BoxGeometry(2.2, 0.5, 1.7);
    const plateMaterial = new THREE.MeshPhongMaterial({
      color: 0x505050,
      shininess: 15,
      emissive: 0x111111
    });

    const plates = [
      { position: new THREE.Vector3(0, 1.5, 0.8) },
      { position: new THREE.Vector3(0, 2.2, 0.8) },
      { position: new THREE.Vector3(0, 3, 0.8) }
    ];

    plates.forEach((plate) => {
      const armorPlate = new THREE.Mesh(plateGeometry, plateMaterial);
      armorPlate.position.copy(plate.position);
      armorPlate.castShadow = true;
      boss.add(armorPlate);
    });
  }

  private addBossSpecificEffects(boss: THREE.Group, bossId: number) {
    switch (bossId) {
      case 1: // Lich Lord
        this.addLichEffects(boss);
        break;
      case 2: // Golem
        this.addGolemEffects(boss);
        break;
      case 3: // Skeleton King
        this.addSkeletonEffects(boss);
        break;
      case 4: // Dragonlord
        this.addDragonEffects(boss);
        break;
      case 5: // The Great Lord
        this.addLordEffects(boss);
        break;
